--
-- Name: sync_product_stock_from_warehouse(); Type: FUNCTION; Schema: public; Owner: guser
--

CREATE FUNCTION public.sync_product_stock_from_warehouse() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_product_id TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    target_product_id := OLD."productId";
  ELSE
    target_product_id := NEW."productId";
  END IF;

  UPDATE "Product"
  SET stock = COALESCE((
    SELECT SUM(quantity) FROM "WarehouseInventory"
    WHERE "productId" = target_product_id
  ), 0),
  "updatedAt" = NOW()
  WHERE id = target_product_id;

  RETURN NULL;
END;
$$;


ALTER FUNCTION public.sync_product_stock_from_warehouse() OWNER TO guser;

--
-- Name: sync_product_stock_on_product_change(); Type: FUNCTION; Schema: public; Owner: guser
--

CREATE FUNCTION public.sync_product_stock_on_product_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD."productId" <> NEW."productId" THEN
    UPDATE "Product"
    SET stock = COALESCE((
      SELECT SUM(quantity) FROM "WarehouseInventory"
      WHERE "productId" = OLD."productId"
    ), 0),
    "updatedAt" = NOW()
    WHERE id = OLD."productId";
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.sync_product_stock_on_product_change() OWNER TO guser;

